def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marks = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    # Each green rectangle is a canvas; marker stamps are placed only when the center is green.
    for r,c in marks:
        # Only isolated markers embedded in/alongside the green shapes encode patches.
        if grid[r][c] != 3:
            continue
        for rr in range(max(0,r-1),min(h,r+2)):
            for cc in range(max(0,c-1),min(w,c+2)):
                if grid[rr][cc] != 2:
                    out[rr][cc] = 1
    return out

