    greens=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==3]
    if not greens: return out
    # Treat each green rectangle independently; embedded 2s mark centers to stamp.
    # Bounding boxes inferred from green cells; 2 markers are in a region if bounded by its green extent.
    # Green regions are separated by blank space; connected components identify each canvas.
    seen=set(); regions=[]
    for r,c in greens:
        if (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); comp=[]
        while stack:
            y,x=stack.pop(); comp.append((y,x))
            for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                if 0<=yy<h and 0<=xx<w and grid[yy][xx]==3 and (yy,xx) not in seen:
                    seen.add((yy,xx)); stack.append((yy,xx))
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        regions.append((min(rs),max(rs),min(cs),max(cs)))
    for r in range(h):
